function y = smoothSignal(x, window, options)
    arguments
        x (:,1) double {mustBeFinite}
        window (1,1) double {mustBeInteger, mustBePositive} = 5
        options.Method (1,1) string {mustBeMember(options.Method, ["mean","median"])} = "mean"
    end
    if options.Method == "mean"
        y = movmean(x, window);
    else
        y = movmedian(x, window);
    end
end

function out = process(data, varargin)
    p = inputParser;
    p.FunctionName = 'process';
    addRequired(p, 'data', @isnumeric);
    addOptional(p, 'scale', 1, @(v) isnumeric(v) && isscalar(v));
    addParameter(p, 'Method', 'mean', @(s) ismember(s, {'mean','median'}));
    parse(p, data, varargin{:});
    out = p.Results.scale * feval(p.Results.Method, p.Results.data);
end

