function y = normalizeRows(A)
    assert(ismatrix(A), 'myPkg:normalizeRows:notMatrix', 'A must be a matrix.');
    n = vecnorm(A, 2, 2);
    assert(all(n > 0), 'Rows must be nonzero.');
    y = A ./ n;
end

function processFile(fname)
    fid = fopen(fname, 'r');
    assert(fid > 0, 'Cannot open %s', fname);
    closer = onCleanup(@() fclose(fid));

    oldDir = pwd;
    restoreDir = onCleanup(@() cd(oldDir));

    data = fread(fid);   % any error here still closes the file
    disp(numel(data));
end

